    __shared__ float x_sh[MOE_HIDDEN_SIZE];
    __shared__ float act_sh[MOE_INTERMEDIATE_SIZE];
    __shared__ float in_scale_sh[MOE_HIDDEN_BLOCKS];
    __shared__ int topk_id_sh[MOE_TOPK];
    __shared__ float topk_w_sh[MOE_TOPK];

