                        dot2 = fmaf(act_sh[k], w0, dot2);
                        dot2 = fmaf(act_sh[k + 1], w1, dot2);
                        dot2 = fmaf(act_sh[k + 2], w2, dot2);
                        dot2 = fmaf(act_sh[k + 3], w3, dot2);
