            const int rb = d >> 7;
            const uint8_t* __restrict__ row_ptr =
                w2_q + w2_e_base + static_cast<int64_t>(d) * MOE_INTERMEDIATE_SIZE;
            const float* __restrict__ fc2_row_scale = fc2_scale_sh + rb * MOE_INTER_BLOCKS;

            float sum2 = 0.0f;
