        const int w2_e_base = expert * (MOE_HIDDEN_SIZE * MOE_INTERMEDIATE_SIZE);
        const int fc1_s_base = expert * MOE_FC1_SCALES_PER_EXPERT;
        const int fc2_s_base = expert * MOE_FC2_SCALES_PER_EXPERT;

