            const int rb_g = row_g >> 7;
            const int rb_u = row_u >> 7;

            const uint8_t* __restrict__ row_g_ptr =
                w1_q + w1_e_base + row_g * MOE_HIDDEN_SIZE;
            const uint8_t* __restrict__ row_u_ptr =
                w1_q + w1_e_base + row_u * MOE_HIDDEN_SIZE;

            const float* __restrict__ s_g_row = fc1_e_scale + rb_g * MOE_HIDDEN_BLOCKS;
            const float* __restrict__ s_u_row = fc1_e_scale + rb_u * MOE_HIDDEN_BLOCKS;

