    constexpr int D_PER_THREAD = MOE_HIDDEN_SIZE / MOE_THREADS;       // 7
    constexpr int K_PER_THREAD = MOE_INTERMEDIATE_SIZE / MOE_THREADS; // 2

    const int tid = static_cast<int>(threadIdx.x);

